verus! {

    /// Solve the multi‐trip refueling problem.
    ///
    /// Inputs:
    ///   a – total distance between the two endpoints (must be > 0)
    ///   b – vehicle’s fuel capacity (must be > 0)
    ///   f – position of the single station along the route (must be in (0,a))
    ///   k – number of end‐to‐end journeys to perform (must be > 0)
    ///
    /// Output:
    ///   result = −1  if and only if the trip is impossible under the given constraints;
    ///   result =  0  if the trip is possible and no station refueling is ever needed;
    ///   result =  1  if the trip is possible but at least one refueling at the station is required.
    ///
    #[verifier(external_body)]
    fn solve(a: i8, b: i8, f: i8, k: i8) -> (result: i8)
        requires
            a > 0 &&
            b > 0 &&
            f > 0 &&
            k > 0 &&
            f < a;
        ensures
            // result is one of −1,0,1
            result == -1 || result == 0 || result == 1;
        ensures
            // Impossible exactly when capacity is too small for one of the required legs:
            //   – to reach the station from the start
            //   – to reach the far endpoint from the station
            //   – for k > 1, to go from one end to the other and then back to the station
            //   – for k = 1, if you cannot go the whole distance a and also cannot reach the station
            //
            // In all and only these cases we report −1.
            (b < f
             || b < a - f
             || (k > 1 && b < 2*a - f)
             || (k == 1 && b < a && b < f))
            <==> (result == -1);
        ensures
            // If it is not impossible, we never return −1
            (result != -1)
            ==>
            // and exactly one of the two feasible‐cases holds:
            //   • no refuel ever needed  ↔  b >= k*a
            //   • at least one refuel    ↔  b <  k*a
            ( (result == 0) <==> (b >= k * a)
              && 
              (result == 1) <==> (b <  k * a)
            );
}